FUNCTION_BLOCK FB_P04
VAR_INPUT
    VISCOSITY_OK : BOOL;
    PASTE_E_STOP_NC : BOOL;
    DebounceTime : TIME;
    CycleTime : TIME;
END_VAR
VAR_OUTPUT
    VFD_RUN : BOOL;
    PUMP_MAINT_DUE : BOOL;
    PUMP_RUNTIME_ACC : LTIME;
END_VAR
VAR
    tonVis : TON;
    startupCycles : INT := 0;
END_VAR

(* 初态：前两个扫描周期强制安全状态，满足 C10 / 上电首周期要求 *)
IF startupCycles < 2 THEN
    VFD_RUN := FALSE;
    PUMP_MAINT_DUE := FALSE;
    PUMP_RUNTIME_ACC := LTIME#0s;
    tonVis(IN := FALSE, PT := T#0s);
    startupCycles := startupCycles + 1;
ELSE
    (* 去抖：粘度信号有效且无急停时才计时；急停或信号无效立即复位 *)
    tonVis(IN := VISCOSITY_OK AND PASTE_E_STOP_NC, PT := DebounceTime);

    (* 运行许可：急停正常且粘度条件有效 *)
    VFD_RUN := PASTE_E_STOP_NC AND tonVis.Q;

    (* 运行时间累计：仅在运行时按正 CycleTime 累加 *)
    IF VFD_RUN AND CycleTime > T#0s THEN
        PUMP_RUNTIME_ACC := PUMP_RUNTIME_ACC + TIME_TO_LTIME(CycleTime);
    END_IF;

    (* 维护提示：累计达到 500 小时置位并保持，不影响运行许可 *)
    IF PUMP_RUNTIME_ACC >= LTIME#500h THEN
        PUMP_MAINT_DUE := TRUE;
    END_IF;
END_IF

END_FUNCTION_BLOCK
